window.MG_LAZY_DATA["data/lazy/courses/a004-30f33728401b534c.json"]={sha256:"30f33728401b534c5ff3a0ad8946b08b0e56ead48e7ce812e8c78f83d636861f",value:{"id":"a004","title":"晶圓研磨與拋光","titleEn":"Wafer lapping and polishing","category":"semiconductor","subcategory":"substrate","subcategoryTitle":"晶圓與基板","subcategoryTitleEn":"Wafers and substrates","summary":"從鋸切晶圓的厚度與損傷開始，建立研磨、鏡面拋光、清潔與放行之間的證據鏈。","summaryEn":"Build an evidence chain from thickness and saw damage through lapping, mirror polishing, cleaning and release.","status":"guided","kind":"course","stepCount":12,"estimatedMinutes":240,"curriculumVersion":6,"contentStatus":"reviewable-educational-curriculum","depth":4,"languageCoverage":["zh-TW","en"],"scope":"公開原理的十二項教學任務，以自行繪製的示意模型、試算及來源資料進行；未提供工廠實測資料、專有配方或設備操作許可。","scopeEn":"Twelve educational tasks based on public principles, using original schematic models, calculations and referenced material. No factory measurement dataset, proprietary recipe or equipment operating authorization is supplied.","sourceIds":["v6-wafer-sumco","v6-cmp-applied","v3-media-80679a241086"],"diagram":{"type":"wafer","labels":["來料","研磨","損傷整備","鏡面拋光","清潔量測"],"labelsEn":["Incoming","Lapping","Damage preparation","Polishing","Clean and measure"],"original":true,"notToScale":true},"stages":[{"id":"a004-stage01","order":1,"title":"來料與幾何基準","titleEn":"Incoming material and geometry","description":"先辨認材料狀態與量測定義，再規劃可用的去除量。","descriptionEn":"Identify material condition and measurement definitions before allocating removal.","steps":[{"id":"a004-v6-01","order":1,"sequence":1,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-wafer-sumco","v6-cmp-applied"],"prerequisiteIds":[],"title":"辨認裸矽晶圓與薄膜 CMP 的邊界","titleEn":"Distinguish bare-wafer finishing from film CMP","objective":"界定本批晶圓的材料層與後續用途。","objectiveEn":"Identify the material stack and intended next process.","instruction":"畫出鋸切裸矽與已有金屬圖案晶圓的兩種截面；在各截面標記可移除材料、保留材料及下一站需要的表面。比較兩者為何不能共用同一終點判據。","instructionEn":"Draw cross-sections of sawn bare silicon and a patterned metal wafer. Mark removable and retained material and the surface required next. Compare why the two need different endpoint criteria.","observation":"觀察「厚度達標」與「保留薄膜達標」是否指向不同的量測。","observationEn":"Notice whether target wafer thickness and target remaining film require different measurements.","failure":"若把金屬 CMP 的選擇性直接當成裸矽拋光規格，先退回材料清單重新界定。","failureEn":"If metal-CMP selectivity is treated as a bare-silicon specification, revisit the material inventory.","check":"交出兩張截面並為每張指定一項厚度和一項表面驗證。","checkEn":"Submit both cross-sections with one thickness and one surface check for each.","knowledge":[{"id":"a004-v6-01-k1","title":"加工對象","titleEn":"Processing target","text":"裸矽整備處理基板本體；薄膜 CMP 還須保護已形成的材料與圖案。","textEn":"Bare-wafer finishing shapes the substrate; film CMP must also preserve existing layers and patterns."},{"id":"a004-v6-01-k2","title":"終點的意義","titleEn":"Meaning of an endpoint","text":"停止條件取決於下一製程需求，不能只以外觀發亮決定。","textEn":"Stopping depends on the next process, not just a shiny appearance."}],"quiz":{"question":"兩片晶圓同樣發亮，為何仍不能用相同終點放行？","questionEn":"Why can two equally shiny wafers require different release endpoints?","options":["它們需要保留的材料和量測對象不同。","兩種終點都只由晶圓直徑決定。","只需反轉研磨方向，便可共用剩餘材料要求。"],"optionsEn":["They retain different materials and require different measurements.","Both endpoints depend only on wafer diameter.","Reversing polishing direction makes remaining-material requirements interchangeable."],"answer":0,"explanation":"它們需要保留的材料和量測對象不同。 裸矽整備處理基板本體；薄膜 CMP 還須保護已形成的材料與圖案。","explanationEn":"They retain different materials and require different measurements. Bare-wafer finishing shapes the substrate; film CMP must also preserve existing layers and patterns."}},{"id":"a004-v6-02","order":2,"sequence":2,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-wafer-sumco"],"prerequisiteIds":["a004-v6-01"],"title":"建立厚度、彎曲與粗糙度量測圖","titleEn":"Map thickness, bow and roughness","objective":"把不同尺度的表面問題分開記錄。","objectiveEn":"Record surface problems at distinct spatial scales.","instruction":"在自行繪製的九點厚度表填入假設值並註明單位，計算最大與最小差值；另畫整片彎曲輪廓和局部粗糙度截線，避免把三種圖合成單一分數。","instructionEn":"Enter labeled hypothetical values in a nine-point thickness table and compute the maximum-minus-minimum difference. Separately sketch whole-wafer bow and local roughness rather than merging them into one score.","observation":"比較厚度一致但彎曲的晶圓，以及不彎曲但厚度不均的晶圓。","observationEn":"Compare a uniformly thick bowed wafer with a flat-looking wafer of uneven thickness.","failure":"若換夾持方式便改變結果，記錄支撐條件；不要把受力展平當成本體已修正。","failureEn":"If support changes the result, record the fixture condition; forced flattening is not permanent correction.","check":"清楚標明厚度差、整體形狀和局部表面三種證據的量測範圍。","checkEn":"Label the measurement extent of thickness variation, overall shape and local surface texture.","knowledge":[{"id":"a004-v6-02-k1","title":"空間尺度","titleEn":"Spatial scale","text":"平行度、整體形狀與局部粗糙度回答不同問題。","textEn":"Parallelism, overall shape and local roughness answer different questions."},{"id":"a004-v6-02-k2","title":"量測基準","titleEn":"Measurement reference","text":"夾持狀態、取樣位置和邊緣排除區須隨結果保存。","textEn":"Support condition, sampling positions and edge exclusion belong with the result."}],"quiz":{"question":"局部粗糙度降低，能否直接證明全片厚度更均勻？","questionEn":"Does lower local roughness prove improved full-wafer thickness uniformity?","options":["能，局部粗糙度就等於全片平行度。","不能，還需要厚度分布量測。","能，固定放大倍率已足以取代厚度取樣。"],"optionsEn":["Yes; local roughness is the same as full-wafer parallelism.","No; a thickness map is still required.","Yes; fixed magnification replaces thickness sampling."],"answer":1,"explanation":"不能，還需要厚度分布量測。 平行度、整體形狀與局部粗糙度回答不同問題。","explanationEn":"No; a thickness map is still required. Parallelism, overall shape and local roughness answer different questions."}},{"id":"a004-v6-03","order":3,"sequence":3,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-wafer-sumco"],"prerequisiteIds":["a004-v6-02"],"title":"分配鋸切後的材料去除預算","titleEn":"Allocate removal after slicing","objective":"在厚度限制內保留後續整備的餘量。","objectiveEn":"Reserve finishing allowance within the thickness constraint.","instruction":"用紙上厚度帳本列出來料、研磨後、損傷去除後與拋光後四個狀態；自行設定教學數值並逐站相減，檢查最後仍留有修整餘量。","instructionEn":"Build a paper thickness ledger for incoming, lapped, damage-removed and polished states. Use explicitly hypothetical values, subtract each allowance and check that finishing margin remains.","observation":"比較平均厚度足夠但局部最薄點已不足的情況。","observationEn":"Compare an acceptable average thickness with an already insufficient local minimum.","failure":"若預算只用平均值，可能忽略最薄區；回到來料地圖調整分配。","failureEn":"An average-only budget can hide a thin region; revise the allocation using the incoming map.","check":"每一站的移除量與最薄位置均可追溯，且沒有負的剩餘餘量。","checkEn":"Trace every removal allocation and the thinnest location, with no negative remaining allowance.","knowledge":[{"id":"a004-v6-03-k1","title":"去除不可逆","titleEn":"Irreversible removal","text":"後段不能靠拋光補回已移除的矽。","textEn":"Later polishing cannot restore silicon already removed."},{"id":"a004-v6-03-k2","title":"最薄區控制","titleEn":"Minimum-thickness control","text":"放行需考慮局部限制，平均值只能作整體摘要。","textEn":"Local limits matter for release; the average is only a summary."}],"quiz":{"question":"平均厚度尚可，但一區已低於最終要求，應如何判斷？","questionEn":"The average is acceptable but one region is below the final requirement. What follows?","options":["只要中心點達標，其他位置可用平均值代替。","繼續全片均勻去除，直到最薄區回到厚度要求。","不能以平均值掩蓋局部不足，需重新判定可加工性。"],"optionsEn":["If the center passes, other locations may be replaced by the average.","Continue uniform removal until the thinnest region returns to the required thickness.","Reassess processability; the average cannot hide the local shortfall."],"answer":2,"explanation":"不能以平均值掩蓋局部不足，需重新判定可加工性。 後段不能靠拋光補回已移除的矽。","explanationEn":"Reassess processability; the average cannot hide the local shortfall. Later polishing cannot restore silicon already removed."}},{"id":"a004-v6-04","order":4,"sequence":4,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-wafer-sumco"],"prerequisiteIds":["a004-v6-03"],"title":"檢查邊緣完整性與搬運接觸","titleEn":"Inspect edge integrity and handling contact","objective":"辨認可能形成碎屑或後續破片的邊緣狀況。","objectiveEn":"Recognize edge conditions that can generate debris or later fracture.","instruction":"在晶圓圓周示意圖標出缺角、裂紋與正常倒角，另畫載具接觸位置。比較缺陷是否靠近支撐點；只制定影像複查與隔離決策，不實作破壞試驗。","instructionEn":"Mark chips, cracks and normal bevels on an edge diagram, then add carrier contact locations. Compare defects with support points and define image review or quarantine decisions without destructive testing.","observation":"注意「平滑倒角」與不規則缺口的形狀差異，以及缺口附近的散落粒子。","observationEn":"Distinguish a smooth bevel from an irregular chip and look for nearby debris.","failure":"把正常倒角誤判為缺角會造成誤剔除；只看中心表面則可能漏掉裂紋。","failureEn":"Mistaking a bevel for a chip causes false rejects; viewing only the center can miss cracks.","check":"缺陷紀錄包含圓周位置、形貌與處置理由，而非只有合格勾選。","checkEn":"Record edge position, morphology and disposition reasoning rather than a pass check alone.","knowledge":[{"id":"a004-v6-04-k1","title":"邊緣應力","titleEn":"Edge stress","text":"邊緣形貌影響接觸與應力集中，也可能成為粒子來源。","textEn":"Edge geometry influences contact and stress concentration and can become a particle source."},{"id":"a004-v6-04-k2","title":"缺陷定位","titleEn":"Defect localization","text":"同一方位重複出現缺口可提示搬運或載具接觸問題。","textEn":"Repeated chips at the same orientation can suggest a handling or carrier-contact issue."}],"quiz":{"question":"缺口總在同一載具接觸附近出現，優先比較什麼？","questionEn":"Chips repeatedly occur near one carrier contact. What should be compared first?","options":["接觸位置與缺陷方位的關聯。","僅比較中心粗糙度，因為邊緣缺陷一定來自中心。","直接歸因於來料批次，不核對載具方位。"],"optionsEn":["The relationship between contact position and defect orientation.","Compare center roughness only, assuming every edge defect originates at the center.","Attribute it to incoming lots without checking carrier orientation."],"answer":0,"explanation":"接觸位置與缺陷方位的關聯。 邊緣形貌影響接觸與應力集中，也可能成為粒子來源。","explanationEn":"The relationship between contact position and defect orientation. Edge geometry influences contact and stress concentration and can become a particle source."}}]},{"id":"a004-stage02","order":2,"title":"研磨與表面整備","titleEn":"Lapping and surface preparation","steps":[{"id":"a004-v6-05","order":1,"sequence":5,"title":"推演雙面研磨的厚度修正","titleEn":"Model thickness correction during lapping","locked":true,"prerequisiteIds":["a004-v6-04"],"sourceIds":["v6-wafer-sumco"],"knowledge":[],"quiz":{"question":"","questionEn":"","options":["","",""],"optionsEn":["","",""],"answer":0}},{"id":"a004-v6-06","order":2,"sequence":6,"title":"區分機械損傷去除與鏡面外觀","titleEn":"Separate damage removal from mirror appearance","locked":true,"prerequisiteIds":["a004-v6-05"],"sourceIds":["v6-wafer-sumco"],"knowledge":[],"quiz":{"question":"","questionEn":"","options":["","",""],"optionsEn":["","",""],"answer":0}},{"id":"a004-v6-07","order":3,"sequence":7,"title":"分解研磨墊、漿料與相對運動","titleEn":"Separate pad, slurry and relative motion","locked":true,"prerequisiteIds":["a004-v6-06"],"sourceIds":["v6-wafer-sumco","v6-cmp-applied"],"knowledge":[],"quiz":{"question":"","questionEn":"","options":["","",""],"optionsEn":["","",""],"answer":0}},{"id":"a004-v6-08","order":4,"sequence":8,"title":"追蹤工具狀態與批次漂移","titleEn":"Track tool condition and lot drift","locked":true,"prerequisiteIds":["a004-v6-07"],"sourceIds":["v6-wafer-sumco","v6-cmp-applied"],"knowledge":[],"quiz":{"question":"","questionEn":"","options":["","",""],"optionsEn":["","",""],"answer":0}}]},{"id":"a004-stage03","order":3,"title":"拋光與驗證","titleEn":"Polishing and verification","steps":[{"id":"a004-v6-09","order":1,"sequence":9,"title":"評估中心與邊緣去除分布","titleEn":"Evaluate center-to-edge removal","locked":true,"prerequisiteIds":["a004-v6-08"],"sourceIds":["v6-cmp-applied","v6-wafer-sumco"],"knowledge":[],"quiz":{"question":"","questionEn":"","options":["","",""],"optionsEn":["","",""],"answer":0}},{"id":"a004-v6-10","order":2,"sequence":10,"title":"建立拋光終點與過拋辨識","titleEn":"Define a polishing endpoint","locked":true,"prerequisiteIds":["a004-v6-09"],"sourceIds":["v6-wafer-sumco","v6-cmp-applied"],"knowledge":[],"quiz":{"question":"","questionEn":"","options":["","",""],"optionsEn":["","",""],"answer":0}},{"id":"a004-v6-11","order":3,"sequence":11,"title":"追蹤拋光後粒子與再污染","titleEn":"Trace particles and recontamination","locked":true,"prerequisiteIds":["a004-v6-10"],"sourceIds":["v6-wafer-sumco","v6-cmp-applied"],"knowledge":[],"quiz":{"question":"","questionEn":"","options":["","",""],"optionsEn":["","",""],"answer":0}},{"id":"a004-v6-12","order":4,"sequence":12,"title":"整合晶圓放行與異常處置","titleEn":"Integrate wafer release and disposition","locked":true,"prerequisiteIds":["a004-v6-11"],"sourceIds":["v6-wafer-sumco","v6-cmp-applied"],"knowledge":[],"quiz":{"question":"","questionEn":"","options":["","",""],"optionsEn":["","",""],"answer":0}}]}],"previewOnly":true,"freeStagesPerCourse":1}};
